@login_required
@require_POST
def revert_page_revision_view(request, revision_id):
    revision = get_object_or_404(Revision, id=revision_id)
    page = revision.content_object.specific
    page_perms = page.permissions_for_user(request.user)
    if not (page_perms.can_edit() and page_perms.can_publish()):
        raise PermissionDenied("Insufficient permissions to revert and publish this page revision.")
    revision.publish()
    return JsonResponse({'status': 'reverted and published', 'page_id': page.id, 'revision_id': revision.id})
